// Normalises the incoming questionType / prompt so downstream parsing can branch on it.
const input = $input.first().json;
const prompt = (input.questionPrompt || '').toLowerCase().replace(/🔹/g, '');

let questionType = (input.questionType || '').toUpperCase();
if (!['MCQ','VSA','SA','LA','A&R','AR','CASE_STUDY'].includes(questionType)) {
  if (prompt.includes('multiple choice') || prompt.includes('mcq')) questionType = 'MCQ';
  else if (prompt.includes('very short') || prompt.includes(' vsa')) questionType = 'VSA';
  else if (prompt.includes('long answer') || prompt.includes(' la ')) questionType = 'LA';
  else if (prompt.includes('short answer') || prompt.includes(' sa ')) questionType = 'SA';
  else if (prompt.includes('assertion') && prompt.includes('reason')) questionType = 'A&R';
  else if (prompt.includes('case study') || prompt.includes('case_study')) questionType = 'CASE_STUDY';
}
// Canonicalise.
if (questionType === 'AR') questionType = 'A&R';

return [{ json: { ...input, QuestionType: questionType } }];

// Parse the LLM HTML output into one item per question, branching on QuestionType.
const input = $input.first().json;
let html = (input.output || '').replace(/```html/gi, '').replace(/```/g, '').trim();

const ref = $('When Executed by Another Workflow').first().json;
const qType = $('Extract QuestionType').first().json.QuestionType;

const blocks = html
  .split('<p>QUESTION_START</p>')
  .map(b => b.trim())
  .filter(Boolean);

function parseMcqLike(block) {
  let correct = '';
  const m = block.match(/Answer\s*:\s*([A-D,\s]+)/i);
  if (m) correct = m[1].replace(/\s+/g, '');
  const cleaned = block.replace(/Answer\s*:[\s\S]*/gi, '').trim();

  const qParts = [];
  const ulIdx = cleaned.indexOf('<ul>');
  const pRe = /<p>([\s\S]*?)<\/p>/gi;
  let pm;
  while ((pm = pRe.exec(cleaned)) !== null) {
    if (ulIdx !== -1 && pm.index > ulIdx) break;
    qParts.push(`<p>${pm[1].trim()}</p>`);
  }
  const question_text = qParts.join('');

  const optRe = /<li>\s*([A-D])\]\s*([\s\S]*?)<\/li>/gi;
  const options = {};
  let om;
  while ((om = optRe.exec(cleaned)) !== null) options[om[1]] = om[2].trim();

  return { question_text, options, correct_option: correct, model_answer: null };
}

function parseWritten(block) {
  const m = block.match(/<p>\s*Answer\s*:\s*([\s\S]*?)<\/p>/i);
  const model_answer = m ? m[1].trim() : '';
  const cleaned = block.replace(/<p>\s*Answer\s*:[\s\S]*?<\/p>/i, '').trim();
  const pRe = /<p>([\s\S]*?)<\/p>/gi;
  const qParts = [];
  let pm; while ((pm = pRe.exec(cleaned)) !== null) qParts.push(`<p>${pm[1].trim()}</p>`);
  return { question_text: qParts.join(''), options: {}, correct_option: '', model_answer };
}

function parseCaseStudy(block) {
  // Keep the whole HTML for case studies; the structure is richer than a single Q.
  const passageMatch = block.match(/<p>\s*Passage[:\s][\s\S]*?<\/p>/i);
  const passage = passageMatch ? passageMatch[0] : '';
  return { question_text: passage || block, options: {}, correct_option: '', model_answer: block, raw_html: block };
}

const writtenTypes = new Set(['VSA','SA','LA']);

return blocks.map((block, index) => {
  let parsed;
  if (qType === 'CASE_STUDY')       parsed = parseCaseStudy(block);
  else if (writtenTypes.has(qType))  parsed = parseWritten(block);
  else                               parsed = parseMcqLike(block); // MCQ, A&R

  return {
    json: {
      Metadata: {
        board: ref.Board,
        class: ref.Class,
        subject: ref.Subject,
        chapter_no: ref['Chapter Number'],
        chapter_name: ref['Chapter Name'],
        concept_no: ref['Concept Number'],
        concept_name: ref['Concept Name'],
        question_level: ref.questionLevel,
        question_type: qType
      },
      questionHtml: {
        question_no: `Q${index + 1}`,
        question_text: parsed.question_text,
        options: parsed.options,
        final_answer: {
          correct_option: parsed.correct_option || null,
          model_answer:   parsed.model_answer   || null
        }
      }
    }
  };
});
